from collections import Counter

class Solution:
    def minOperations(self, nums: List[int], target: int) -> int:
        count = Counter(nums)

        if sum(num * count[num] for num in count) < target:
            return -1

        ops = 0
        total = 0

        sorted_nums = sorted(count.keys(), reverse=True)

        for num in sorted_nums:
            while count[num] > 0 and total < target:
                total += num
                count[num] -= 1

            if total >= target:
                break

            while num > 1 and total < target:
                new_num = num // 2
                ops += 1
                count[new_num] += 2
                count[num] -= 1
                total += new_num

                if total >= target:
                    break

        if total < target:
            return -1

        return ops

